export const PRODUCT_BY_KEY = Object.fromEntries(PRODUCTS.map((p) => [p.key, p]))

const PRICE_INDEX = {}
for (const p of PRODUCTS) {
  for (const [cycle, variants] of Object.entries(p.prices)) {
    for (const [variant, priceId] of Object.entries(variants)) {
      PRICE_INDEX[priceId] = { key: p.key, cycle, variant }
    }
  }
}

export function lookupPrice(priceId) {
  return PRICE_INDEX[priceId] || null
}

export function priceFor(key, cycle, variant) {
  return PRODUCT_BY_KEY[key]?.prices?.[cycle]?.[variant] || null
}

export function formatUsd(cents) {
  return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(cents / 100)
}
